var native_tool_row_default = "/* COPY/ADAPT: DSH 0.2.2-rc.5 ToolRow.module.css (row/summary/fileLink,\n   bodyWrap, ioCard/Section/Label/Divider/Text, terminalBody), and installed\n   native.css TextShimmer _1rdzk 218\u2013301 / DisclosureRow _l4nv8 303\u2013389.\n   Native class hashes are replaced by local names, never imported at runtime.\n   Local adaptations: focus/touch disclosure affordance, compact long titles,\n   retained mounted bodies, safe ACP Markdown inside OUT, and owned scroll state.\n   Native role-button row + child file button preserves click/keyboard isolation. */\n.rssh-native-tool-header { display: flex; align-items: center; min-width: 0; }\n.rssh-native-tool-header[hidden] { display: none; }\n.rssh-native-tool-row {\n  flex: 1 1 auto; position: relative; overflow: hidden; display: flex; align-items: center;\n  min-height: calc(24px + var(--dsh-content-font-delta, 0px)); min-width: 0;\n  color: var(--dsw-alias-label-tertiary); transition: color .1s ease; cursor: pointer;\n}\n.rssh-native-tool-row:focus-visible,\n.rssh-native-tool-file-link:focus-visible,\n.rssh-native-tool-io-section:focus-visible {\n  outline: 2px solid var(--dsw-alias-state-info-primary); outline-offset: 2px; border-radius: 4px;\n}\n.rssh-native-tool-leading {\n  position: relative; flex: none; display: inline-flex; align-items: center; justify-content: center;\n  width: calc(16px + var(--dsh-content-font-delta, 0px)); height: calc(16px + var(--dsh-content-font-delta, 0px));\n  margin-right: 6px; padding: 0; border: none; background: none; color: inherit;\n}\n.rssh-native-tool-leading svg:not([data-state]) {\n  flex: none; margin: 0; width: calc(14px + var(--dsh-content-font-delta, 0px)); height: calc(14px + var(--dsh-content-font-delta, 0px));\n}\n.rssh-native-tool-icon-idle { display: inline-flex; opacity: 1; transition: opacity .1s ease; }\n.rssh-native-tool-leading .rssh-native-tool-chevron-hover { position: absolute; inset: 0; margin: auto; opacity: 0; transition: opacity .1s ease; }\n.rssh-native-tool-title { flex: none; font-weight: 400; font-size: var(--dsh-content-font-size-secondary, 13px); line-height: calc(24px + var(--dsh-content-font-delta, 0px)); color: inherit; white-space: nowrap; }\n.rssh-native-tool-sep { flex: none; width: 2px; height: 2px; border-radius: 1px; margin: 0 8px; background: var(--dsw-alias-label-caption); }\n.rssh-native-tool-summary { flex: 1 1 auto; min-width: 0; overflow: hidden; text-overflow: ellipsis; white-space: nowrap; font-size: var(--dsh-content-font-size-secondary, 13px); line-height: calc(24px + var(--dsh-content-font-delta, 0px)); }\n.rssh-native-tool-file-link {\n  flex: 0 1 auto; min-width: 0; overflow: hidden; text-overflow: ellipsis; white-space: nowrap;\n  margin: 0; padding: 0; border: none; background: none; font: inherit; text-align: left;\n  font-size: var(--dsh-content-font-size-secondary, 13px); line-height: calc(24px + var(--dsh-content-font-delta, 0px)); color: inherit;\n  text-decoration: underline dotted; text-decoration-color: currentColor; text-decoration-thickness: 1px; text-underline-offset: 3px; cursor: pointer;\n}\n.rssh-native-tool-error-summary, .rssh-native-tool-error-detail { color: var(--dsw-alias-state-error-primary); }\n.rssh-native-tool-error-detail { white-space: pre-wrap; overflow-wrap: anywhere; }\n/* Compact mode intentionally retains informative ACP title rather than a bare\n   action label. It is the only case allowed to shrink/truncate the title. */\n.rssh-native-tool-row[data-compact] .rssh-native-tool-title { flex: 0 1 auto; min-width: 0; overflow: hidden; text-overflow: ellipsis; }\n.rssh-native-tool-row[data-compact] .rssh-native-tool-error-summary { flex: 1 0 35%; }\n.rssh-native-tool-shimmer { position: relative; display: inline-grid; width: max-content; max-width: calc(100% - 22px - var(--dsh-content-font-delta, 0px)); min-width: 0; vertical-align: top; color: inherit; }\n.rssh-native-tool-content { display: flex; align-items: center; min-width: 0; }\n.rssh-native-tool-decoration { position: absolute; inset: 0; overflow: clip; pointer-events: none; user-select: none; }\n.rssh-native-tool-sweep { position: absolute; inset: 0; overflow: hidden; color: var(--dsw-alias-label-shimmer); mask-image: linear-gradient(105deg, transparent 0%, black 40% 60%, transparent 100%); transform: translate(-100%); animation-name: rssh-native-tool-shimmer-sweep; }\n.rssh-native-tool-sweep * { color: inherit !important; }\n.rssh-native-tool-sweep [data-shimmer-decoration] { background: currentColor; }\n.rssh-native-tool-highlight { width: 100%; height: 100%; transform: translate(100%); animation-name: rssh-native-tool-shimmer-highlight; }\n.rssh-native-tool-sweep, .rssh-native-tool-highlight { animation-duration: 1.5s; animation-delay: .3s; animation-timing-function: steps(48, end); animation-iteration-count: infinite; }\n@keyframes rssh-native-tool-shimmer-sweep { 0% { transform: translate(-100%); } 66.6667%, to { transform: translate(100%); } }\n@keyframes rssh-native-tool-shimmer-highlight { 0% { transform: translate(100%); } 66.6667%, to { transform: translate(-100%); } }\n@media (hover: hover) {\n  .rssh-native-tool-row:hover { color: var(--dsw-alias-label-secondary); }\n  .rssh-native-tool-row:hover .rssh-native-tool-icon-idle { opacity: 0; }\n  .rssh-native-tool-row:hover .rssh-native-tool-chevron-hover { opacity: 1; }\n}\n.rssh-native-tool-row:focus-visible .rssh-native-tool-icon-idle { opacity: 0; }\n.rssh-native-tool-row:focus-visible .rssh-native-tool-chevron-hover { opacity: 1; }\n@media (hover: none), (pointer: coarse) {\n  .rssh-native-tool-icon-idle { opacity: 0; }\n  .rssh-native-tool-leading .rssh-native-tool-chevron-hover { opacity: 1; }\n}\n@media (pointer: coarse) { .rssh-native-tool-row { min-height: 40px; } }\n@media (prefers-reduced-motion: reduce) {\n  .rssh-native-tool-row, .rssh-native-tool-icon-idle, .rssh-native-tool-leading .rssh-native-tool-chevron-hover { transition: none; }\n  .rssh-native-tool-decoration { display: none; }\n  .rssh-native-tool-sweep, .rssh-native-tool-highlight { animation: none; }\n}\n/* Native body is a column, aligned 4px below the row, not an extra card shell. */\n.rssh-tool-flow > .rssh-flow-body { display: flex; flex-direction: column; padding-inline-start: 4px; margin: 4px 0; }\n.rssh-tool-flow > .rssh-flow-body[hidden] { display: none; }\n.rssh-native-tool-io-card { display: flex; flex-direction: column; min-width: 0; margin: 4px 0; border: .5px solid var(--dsw-alias-border-l1); border-radius: var(--dsw-radius-lg); background: var(--dsw-alias-markdown-code-block); font: var(--dsw-font-markdown-code-block-small); }\n.rssh-native-tool-io-section { display: grid; grid-template-columns: max-content minmax(0, 1fr); column-gap: 14px; align-items: baseline; padding: 12px 16px; max-height: 150px; overflow-y: auto; }\n.rssh-native-tool-io-section::-webkit-scrollbar-thumb { border: 2px solid transparent; background-clip: padding-box; border-radius: var(--dsw-radius-sm); }\n.rssh-native-tool-io-section::-webkit-scrollbar-track { margin: 6px 0; }\n.rssh-native-tool-io-label { position: sticky; top: 0; align-self: start; color: var(--dsw-alias-label-caption); }\n.rssh-native-tool-io-divider { flex: none; height: .5px; background: var(--dsw-alias-border-l2); }\n.rssh-native-tool-io-text { min-width: 0; white-space: pre-wrap; word-break: break-word; color: var(--dsw-alias-label-secondary); }\n.rssh-native-tool-io-text[data-error] { color: var(--dsw-alias-state-error-primary); }\n.rssh-native-tool-io-text .rssh-native-markdown { white-space: normal; color: inherit; }\n/* BashRow / bash-sample.module.css:15\u201322 in installed DSH 0.2.2-rc.5.\n   Keep the Host code-font preference adaptation; restore native command wrapping. */\n.rssh-tool-flow .rssh-native-tool-terminal-body { --rssh-native-terminal-command-whitespace: pre-wrap; --rssh-native-terminal-output-max-height: 224px; border: .5px solid var(--dsw-alias-border-l1); }\n.rssh-tool-flow .rssh-native-tool-terminal-body .rssh-native-terminal-output { max-height: var(--rssh-native-terminal-output-max-height); overflow-y: auto; }\n.rssh-tool-flow :is(.rssh-native-tool-terminal-body,.rssh-native-tool-diff-body,.rssh-native-tool-read-body) { margin: 4px 0; }\n/* Owned bounded process lists remain the single vertical reading viewport.\n   Standalone cards retain native caps; nested cards do not steal tail gestures. */\n.rssh-process-disclosure[data-scroll-body] :is(.rssh-native-tool-io-section, .rssh-native-tool-terminal-body .rssh-native-terminal-output) { max-height: none; overflow-y: visible; }\n";

